import type { ReactNode } from 'react';
import { memo, useState, useRef, useMemo, useCallback, useEffect } from 'react';

import { renderToStaticMarkup } from 'react-dom/server';

import { useTranslation } from 'react-i18next';

import { useTheme } from '@mui/material/styles';

import Markdown from 'markdown-to-jsx';

import { Box } from '@/ui';
import type { LayerListEntry } from '@/core/components/common';
import { Layout } from '@/core/components/common';
import type { TypeContainerBox } from '@/core/types/global-types';
import type { TypeGuideObject } from '@/core/stores/states/app-state';
import { useStoreAppGuide } from '@/core/stores/states/app-state';
import { useStoreGeoViewMapId } from '@/core/stores/geoview-store';
import { TABS, TIMEOUT } from '@/core/utils/constant';
import { logger } from '@/core/utils/logger';
import { transformMarkdownIds } from '@/core/utils/utilities';
import { getGVGuidebox } from '@/core/utils/dom-helper';
import { getSxClasses } from './guide-style';
import { GuideSearch } from './guide-search';
import type { SxStyles } from '@/ui/style/types';

/** Guide list item extending LayerListEntry with content. */
interface GuideListItem extends LayerListEntry {
  /** The rendered guide content. */
  content: string | ReactNode;
}

/** Props for the Guide component. */
interface GuideType {
  /** The container box type for layout. */
  containerType: TypeContainerBox;
}

/** Individual guide item type (value of TypeGuideObject). */
type GuideItem = TypeGuideObject[string];

/**
 * Creates the guide component to display help content.
 *
 * Memoized to prevent re-renders when parent updates but containerType has not changed.
 *
 * @param props - Properties defined in GuideType interface
 * @returns The guide component
 */
export const Guide = memo(({ containerType }: GuideType): JSX.Element => {
  logger.logTraceRender('components/guide/guide');

  // Store
  const guide = useStoreAppGuide();
  const mapId = useStoreGeoViewMapId();

  // Hooks
  const { t } = useTranslation<string>();
  const theme = useTheme();
  const memoSxClasses = useMemo((): SxStyles => {
    logger.logTraceUseMemo('GUIDE - memoSxClasses', theme);
    return getSxClasses(theme);
  }, [theme]);

  // State
  const [selectedLayerPath, setSelectedLayerPath] = useState<string>('loadingStatus');
  const [guideItemIndex, setGuideItemIndex] = useState<number>(0);
  const [highlightFunction, setHighlightFunction] = useState<(content: string, sectionIndex: number) => string>(
    () => (content: string) => content
  );
  const [isFullScreen, setIsFullScreen] = useState(false);

  // Refs
  const rootRef = useRef<HTMLDivElement>(null);
  /** Tracks pending RAF for scroll reset to enable cleanup. */
  const rafIdRef = useRef<number | undefined>(undefined);
  /** Tracks pending focus timeout to enable cleanup. */
  const focusTimeoutRef = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);

  // #region Handlers

  /**
   * Handles search state changes from GuideSearch component.
   */
  const handleSearchStateChange = useCallback(
    (_newSearchTerm: string, newHighlightFunction: (content: string, sectionIndex: number) => string): void => {
      setHighlightFunction(() => newHighlightFunction);
    },
    []
  );

  /**
   * Creates a markdown component with the given content.
   *
   * @param content - The markdown content string
   * @returns The rendered markdown component
   */
  const createMarkdownComponent = useCallback(
    (content: string): JSX.Element => <Markdown options={{ wrapper: 'article' }}>{content}</Markdown>,
    []
  );

  /**
   * Concatenates guide content with all nested child and grandchild content.
   *
   * Uses \n\n (blank line) separators so markdown-to-jsx treats each section as a new block.
   * A single \n after a list item causes the following heading to be parsed as a lazy
   * continuation line inside the <li>.
   *
   * @param guideItem - The guide item to concatenate
   * @returns The concatenated content string with unique IDs
   */
  const concatenateGuideContent = useCallback(
    (guideItem: GuideItem): string => {
      let { content } = guideItem;

      if (guideItem.children) {
        Object.entries(guideItem.children).forEach(([, child]: [string, GuideItem]) => {
          content += `\n\n${child.content}`;

          if (child.children) {
            Object.values(child.children).forEach((grandChild: GuideItem) => {
              content += `\n\n${grandChild.content}`;
            });
          }
        });
      }

      // Transform IDs to be unique for this map/container instance
      return transformMarkdownIds(content, `${mapId}-${containerType}`);
    },
    [mapId, containerType]
  );

  /**
   * Builds the memoized layer list with markdown content.
   */
  const memoLayersList = useMemo((): GuideListItem[] => {
    logger.logTraceUseMemo('GUIDE - memoLayersList', guide, mapId, containerType);

    if (!guide) return [];

    return Object.keys(guide).map((item: string) => {
      const content = concatenateGuideContent(guide[item]);

      return {
        layerName: guide[item].heading,
        layerPath: item,
        layerStatus: 'loaded',
        queryStatus: 'processed',
        content: createMarkdownComponent(content),
        layerUniqueId: `${mapId}-${containerType}-${TABS.GUIDE}-${item ?? ''}`,
      };
    });
  }, [guide, mapId, containerType, concatenateGuideContent, createMarkdownComponent]);

  /**
   * Handles section change from GuideSearch component.
   */
  const handleSectionChange = useCallback(
    (sectionIndex: number): void => {
      if (memoLayersList[sectionIndex]) {
        setGuideItemIndex(sectionIndex);
        setSelectedLayerPath(memoLayersList[sectionIndex].layerPath);
      }
    },
    [memoLayersList]
  );

  /**
   * Builds the current guide content with search highlighting applied.
   */
  const memoCurrentGuideContent = useMemo((): ReactNode => {
    logger.logTraceUseMemo('GUIDE - memoCurrentGuideContent', memoLayersList, guideItemIndex, guide, highlightFunction);

    const currentItem = memoLayersList[guideItemIndex];
    if (!currentItem || !guide) return null;

    const currentGuideKey = Object.keys(guide)[guideItemIndex];
    if (!currentGuideKey) return currentItem.content;

    const content = concatenateGuideContent(guide[currentGuideKey]);

    // Convert markdown to HTML React elements
    const markdownElement = <Markdown>{content}</Markdown>;

    // Convert React element to HTML string
    const htmlString = renderToStaticMarkup(markdownElement);

    // Apply highlighting to the HTML
    const highlightedHTML = highlightFunction(htmlString, guideItemIndex);

    // GV: dangerouslySetInnerHTML is safe here because:
    // 1. Content originates from trusted markdown files in the codebase (guide.md)
    // 2. Markdown is converted to HTML via markdown-to-jsx (sanitized React elements)
    // 3. HTML is then processed to add <mark> tags for search highlighting
    // 4. No user-generated content is involved in this process
    // eslint-disable-next-line react/no-danger
    return <article dangerouslySetInnerHTML={{ __html: highlightedHTML }} />;
  }, [memoLayersList, guideItemIndex, guide, highlightFunction, concatenateGuideContent]);

  /**
   * Handles guide layer list item click.
   */
  const handleGuideItemClick = useCallback(
    (layer: LayerListEntry): void => {
      const index: number = memoLayersList.findIndex((item) => item.layerName === layer.layerName);
      setGuideItemIndex(index);
      setSelectedLayerPath(layer.layerPath);
    },
    [memoLayersList]
  );

  /**
   * Handles fullscreen state changes from the Layout component.
   */
  const handleFullScreenChanged = useCallback((fullScreen: boolean): void => {
    setIsFullScreen(fullScreen);
  }, []);

  // #endregion Handlers

  /**
   * Resets scroll position and handles anchor link navigation when content changes.
   */
  useEffect(() => {
    logger.logTraceUseEffect('GUIDE - anchor link navigation and scroll reset', selectedLayerPath, guideItemIndex, isFullScreen);

    // Find the guidebox-container (visible copy; portaled out of the map root in fullscreen)
    const guideboxContainer = getGVGuidebox(mapId);

    if (!guideboxContainer) {
      return;
    }

    // Find the scrollable container by walking up from guidebox-container
    const container = isFullScreen
      ? guideboxContainer.closest('.MuiDialogContent-root') // Walk up to Dialog content
      : guideboxContainer.parentElement; // Just get parent

    if (!container) {
      return;
    }

    // Reset scroll position when content changes
    rafIdRef.current = requestAnimationFrame(() => {
      container.scrollTo({
        top: 0,
        behavior: 'instant',
      });
    });

    const handleClick = (e: Event): void => {
      const target = e.target as HTMLAnchorElement;
      if (target.tagName === 'A' && target.hash) {
        e.preventDefault();
        e.stopPropagation();

        // Query for the target element using the hash
        // Hash includes the transformed prefix (mapId-containerType-originalId)
        // ensuring it finds the correct element in this specific guide instance.
        // Extract ID from hash (remove leading #) and escape for safe querySelector usage
        // to handle IDs with special CSS selector characters like :, ., [, ], etc.
        const targetId = target.hash.slice(1);
        const element = container.querySelector(`#${CSS.escape(targetId)}`);

        if (element) {
          // Add tabindex="-1" if the element doesn't have one
          if (!element.hasAttribute('tabindex')) {
            element.setAttribute('tabindex', '-1');
          }

          const elementPosition = element.getBoundingClientRect().top;
          const containerPosition = container.getBoundingClientRect().top;
          const scrollPosition = elementPosition - containerPosition + container.scrollTop;

          container.scrollTo({
            top: scrollPosition,
            behavior: 'smooth',
          });

          // Clear any existing timeout before scheduling a new one
          if (focusTimeoutRef.current !== undefined) {
            clearTimeout(focusTimeoutRef.current);
          }

          // Set focus on the target element after scrolling
          focusTimeoutRef.current = setTimeout(() => {
            // Explicitly request focus indicator for keyboard users
            (element as HTMLElement).focus({ preventScroll: true, focusVisible: true });
          }, TIMEOUT.guideAnchorFocus);
        }
      }
    };

    container.addEventListener('click', handleClick);

    // Cleanup function to remove the event listener and cancel pending async operations
    return () => {
      container.removeEventListener('click', handleClick);
      if (rafIdRef.current !== undefined) {
        cancelAnimationFrame(rafIdRef.current);
      }
      if (focusTimeoutRef.current !== undefined) {
        clearTimeout(focusTimeoutRef.current);
      }
    };
    // Note: selectedLayerPath and guideItemIndex are trigger tokens — their identity change drives scroll reset even though values aren't consumed
  }, [selectedLayerPath, guideItemIndex, isFullScreen, mapId]);

  const ariaLabel = t('guide.title');
  return (
    <Box ref={rootRef} sx={memoSxClasses.guideContainer}>
      <Box sx={{ flex: 1, minHeight: 0 }}>
        <Layout
          containerType={containerType}
          titleFullscreen={t('guide.title')}
          selectedLayerPath={selectedLayerPath}
          onFullScreenChanged={handleFullScreenChanged}
          layoutSwitch={
            <GuideSearch
              containerType={containerType}
              guide={guide}
              onSectionChange={handleSectionChange}
              onSearchStateChange={handleSearchStateChange}
            />
          }
          layerList={memoLayersList}
          onLayerListClicked={handleGuideItemClick}
          hideAvailableHeading
          aria-label={ariaLabel}
        >
          <Box sx={memoSxClasses.rightPanelContainer} className="guidebox-container" data-map-id={mapId}>
            <Box sx={memoSxClasses.guideBox}>{memoCurrentGuideContent}</Box>
          </Box>
        </Layout>
      </Box>
    </Box>
  );
});
Guide.displayName = 'Guide';
